const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Monte Pisano area in Northern Italy (approximate bounding box)
  const geometry = ee.Geometry.Polygon([
    [10.4, 43.7],
    [10.6, 43.7],
    [10.6, 43.8],
    [10.4, 43.8],
    [10.4, 43.7]
  ]);

  const startDate = '2019-02-24';
  const endDate = '2019-02-26';

  // 2. Data Acquisition - VIIRS Active Fires
  const fireCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  const collectionSize = fireCollection.size().getInfo();
  console.log(`Fire detection images found: ${collectionSize}`);

  // Check for empty collection
  if (collectionSize === 0) {
    console.log("No fire detection data available for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count fire pixels
  // Create a binary mask for fire pixels (confidence > 0)
  const fireMask = fireCollection.map(function(image) {
    return image.select('Confidence').gt(0);
  });

  // Combine all fire masks and count total fire pixels
  const totalFireMask = fireMask.sum();

  const fireCount = totalFireMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('Confidence').getInfo();

  console.log(`Total fire pixels detected: ${fireCount}`);

  // 4. Validation & Final Answer
  if (fireCount === null || fireCount === undefined) {
    console.log("<answer>C3</answer>");
  } else if (fireCount > 0) {
    console.log("Active fires detected in the area.");
    console.log("<answer>A</answer>");
  } else {
    console.log("No active fires detected in the area.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
